'use strict';
// Writes vectors.json, the conformance vectors for the shim's wire contract
// (docs/superpowers/specs/2026-11-15-shared-runtime-design.md, section 1).
// The Rust shim and the runtime's session listener both run them. Fixed
// inputs, so the file is the same each run:
//   node docs/superpowers/specs/shared-runtime-wire/make-vectors.js
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const hex = (b) => Buffer.from(b).toString('hex');
const b64 = (b) => Buffer.from(b).toString('base64');
const fill = (n, start) => Buffer.from(Array.from({length: n}, (_, i) => (start + i) & 0xff));
const hmac = (secret, ...parts) => crypto.createHmac('sha256', secret).update(Buffer.concat(parts.map((p) => Buffer.from(p)))).digest();

// kind byte, u32 big-endian payload length, payload
function frame(kind, payload) {
  const body = Buffer.isBuffer(payload) ? payload : Buffer.from(payload, 'utf8');
  const head = Buffer.alloc(5);
  head.write(kind, 0, 'ascii');
  head.writeUInt32BE(body.length, 1);
  return Buffer.concat([head, body]);
}
// an M frame's payload: u16 big-endian header length, the header JSON (none
// when 0), then the message's bytes
function mPayload(header, message) {
  const h = header == null ? Buffer.alloc(0) : Buffer.from(JSON.stringify(header), 'utf8');
  const len = Buffer.alloc(2);
  len.writeUInt16BE(h.length, 0);
  return Buffer.concat([len, h, Buffer.isBuffer(message) ? message : Buffer.from(message, 'utf8')]);
}
const json = (o) => JSON.stringify(o);
// a hidden character: one a reader doesn't see (see conditionsWhy.hiddenClass)
const HIDDEN_CLASS = '\\u0000-\\u001f\\u007f-\\u009f\\u00ad\\u034f\\u061c\\u115f\\u1160\\u180e\\u200b-\\u200f\\u2028-\\u202e\\u2060-\\u2069\\u2800\\u3164\\ud800-\\udfff\\ufe00-\\ufe0f\\ufeff\\uffa0\\ufff9-\\ufffb\\u{1d173}-\\u{1d17a}\\u{e0000}-\\u{e007f}\\u{e0100}-\\u{e01ef}';

// Plainly made-up inputs (repeated bytes, example names), so no value here
// reads as a credential to a secret scanner. Each MAC is derived from them.
const secret = Buffer.alloc(32, 0x5a);
const nc = Buffer.alloc(32, 0x6e);
const ns = Buffer.alloc(32, 0x73);
const P = Buffer.from([1]);   // HELLO's protocol, one byte
const ms = hmac(secret, 'ch-server', P, nc, ns);
const mc = hmac(secret, 'ch-client', P, ns, nc);
const token = 'example-token-not-a-real-one';
// a pack credential the client's environment chooses (ch-local's conditions
// child names it from the installed packs, never from the environment)
const credName = 'PACK_VAR_ALPHA';
const credValue = 'example-value-not-a-real-one';
const credMac = hmac(secret, 'ch-cred', Buffer.from(credName, 'utf8'), Buffer.from([0]), Buffer.from(credValue, 'utf8'));

const hello = json({protocol: 1, nc: b64(nc)});
const prove = json({ns: b64(ns), ms: b64(ms)});
const auth = json({mc: b64(mc)});
const authResume = json({mc: b64(mc), resume: 'rt_example_resume_value'});
const welcome = json({session: 's_example_session', resumeToken: 'rt_example_resume_value', runtimeVersion: '8.0.0', maxToRuntime: 8388608 + 4096, maxToShim: 2 * 268435456 + 1048576});
// maxToRuntime: the default --maxRequestBody (8 MiB) + 4096; maxToShim: twice
// 256 MiB (no ceiling) + 1 MiB, as section 1 has them
const refused = json({code: 'BAD_PROOF', message: 'the client\'s proof did not match'});
const request = '{"jsonrpc":"2.0","id":7,"method":"tools/call","params":{"name":"x","arguments":{"é":"✓"}}}';
const reply = '{"jsonrpc":"2.0","id":7,"result":{"content":[],"resultType":"complete"}}';
const notification = '{"jsonrpc":"2.0","method":"notifications/tools/list_changed"}';
// With a token chosen, the client frame's `token` field holds tokenMac.macB64.
const client = json({op: 'client', status: 'ok', conditions: 'yes', repo: 'acme/widgets', token: null});
const clientNoToken = json({op: 'client', status: 'ok', conditions: 'no', repo: null, token: null});
const clientFailed = json({op: 'client', status: 'failed', why: 'the conditions check timed out after 10 s'});
const clientCredentials = json({op: 'client', status: 'ok', conditions: 'no', repo: null, token: null, credentials: {[credName]: b64(credMac)}});
const clientAnswer = json({op: 'client', seq: 3, status: 'ok', conditions: 'yes', repo: 'acme/widgets', token: null});
const batch = '[{"jsonrpc":"2.0","id":1,"method":"tools/list"},{"jsonrpc":"2.0","method":"notifications/cancelled","params":{"requestId":0}},{"jsonrpc":"2.0","id":"b","method":"tools/list"}]';
const odd = '{"jsonrpc":"2.0","id":1e2,"method":"tools/list"}';
